import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, qty, seq, active)
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def add_to_book(side, oid, price, qty):
        seq = next_seq()
        orders_info[oid] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, oid))
        else:
            heapq.heappush(sell_heap, (price, seq, oid))

    def match_incoming(side, oid, price, qty, is_market=False):
        # price is None if market order (no price limit)
        remaining = qty
        if side == 'buy':
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                info = orders_info.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(sell_heap)
                    continue
                if (not is_market) and top_price > price:
                    break
                # match
                heapq.heappop(sell_heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                else:
                    heapq.heappush(sell_heap, (top_price, top_seq, top_id))
            return remaining
        else:
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                info = orders_info.get(top_id)
                if info is None or not info['active'] or info['qty'] <= 0:
                    heapq.heappop(buy_heap)
                    continue
                if (not is_market) and top_price < price:
                    break
                heapq.heappop(buy_heap)
                trade_qty = min(remaining, info['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    info['active'] = False
                else:
                    heapq.heappush(buy_heap, (neg_price, top_seq, top_id))
            return remaining

    for order in orders:
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, oid, price, qty, is_market=False)
            if remaining > 0:
                add_to_book(side, oid, price, remaining)
            else:
                orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': next_seq(), 'active': False}
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            remaining = match_incoming(side, oid, price, qty, is_market=False)
            orders_info[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': next_seq(), 'active': False}
        elif typ == 'market':
            _, oid, side, qty = order
            remaining = match_incoming(side, oid, None, qty, is_market=True)
            orders_info[oid] = {'side': side, 'price': None, 'qty': 0, 'seq': next_seq(), 'active': False}
        elif typ == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['active']:
                info['active'] = False
                info['qty'] = 0

    return trades

